insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('18dfd61e-7c87-45ee-9e64-4c9041b56d64', 'seed_RDdeYbUG3VB92nDL7nmv8bJq1W5x', '2026-05-29T21:53:43.000Z', 'A Practical Guide to Design-Build Delivery in Oil and Gas', 'a-practical-guide-to-design-build-delivery-in-oil-and-gas', 'Design build: how design-build delivery cuts cost and schedule risk on Oil and Gas projects in northern Alberta. Includes a checklist for owners, contractors and site teams working through the next season.', null, null, null, '{}', array['construction', 'oil and gas'], 'Marcus Okafor', '2026-07-14', 'Lessons learned only count if the next project actually reads them. Owners who treat design-build delivery as a box to tick usually discover the cost during construction. Weather, remote access and short construction seasons in northern Alberta all raise the stakes. Field crews should be involved before drawings are issued for construction, not after.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('8569074e-f3cf-4d5f-b1a0-a5e4a58d77e5', 'seed_cqj2S1QHvJYXdj6qw2qnpLVeWUSu', '2026-03-29T22:01:43.000Z', 'Integrated EPC Solutions: What Water and Wastewater Owners Should Know', 'integrated-epc-solutions-what-water-and-wastewater-owners-should-know', 'Integrated EPC solutions: how integrated EPC delivery cuts cost and schedule risk on Water and Wastewater projects in Saskatchewan.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'engineering'), 'Integrated EPC solutions', array['Construction project management'], array['engineering', 'water and wastewater'], 'Marcus Okafor', '2026-05-13', 'When Water and Wastewater owners in Saskatchewan search for "Integrated EPC solutions", they usually want one thing: a project that stays on budget and on schedule. When equipment arrives late, every downstream trade waits, and the camp costs keep running. The first step is agreeing what a good outcome looks like before the design is frozen. Owners who treat integrated EPC delivery as a box to tick usually discover the cost during construction. Lessons learned only count if the next project actually reads them.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('1636524c-8b59-4cd2-bdea-4e3f4cd57a69', 'seed_LkNvqWK0WWB1cavZBLgb8eSbUoeo', '2026-04-04T16:21:52.000Z', '5 Lessons on EPC Construction from Western Canada Projects', '5-lessons-on-epc-construction-from-western-canada-projects', 'EPC construction for Petrochemicals owners in Western Canada: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'construction'), 'EPC construction', '{}', array['construction'], 'Amira Haddad', '2026-05-20', 'When Petrochemicals owners in Western Canada search for "EPC construction", they usually want one thing: a project that stays on budget and on schedule. Digital tools help, but only if the people using them trust the information inside. That means naming one accountable person and a clear decision date. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it. Weather, remote access and short construction seasons in Western Canada all raise the stakes.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('2b6a1b77-d942-4797-a6cd-007d7a339241', 'seed_Lk2JKr56DvH6fcFfwRwn2VTU2mPM', '2026-05-02T10:57:43.000Z', '5 Lessons on Procurement from Saskatchewan Projects', '5-lessons-on-procurement-from-saskatchewan-projects', 'Practical lessons from Petrochemicals projects in Saskatchewan on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'procurement'), 'Procurement', '{}', array['procurement', 'petrochemicals'], null, '2026-06-01', '', 'draft', '5c19510d-ff8c-4865-82f2-5de5991a9ae0', null, null, null, null, null, '2026-05-06T10:57:43.000Z', '2026-05-06T10:57:43.000Z');
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('e2b9ac62-f39c-4de6-8919-6ddb901475fb', 'seed_ZGgYpn19sAMU3r74jqaU6ptXd9bV', '2026-07-04T15:49:27.000Z', 'Pre Construction: Lessons from an Alberta Pipeline Terminal', 'pre-construction-lessons-from-an-alberta-pipeline-terminal', 'Pre construction: how pre-construction planning cuts cost and schedule risk on Renewables projects in Saskatchewan.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'construction'), 'Pre construction', '{}', array['construction'], 'EPCMst Team', '2026-08-06', 'When Renewables owners in Saskatchewan search for "Pre construction", they usually want one thing: a project that stays on budget and on schedule. When equipment arrives late, every downstream trade waits, and the camp costs keep running. Measuring progress weekly, with the same yardstick, keeps surprises small. Digital tools help, but only if the people using them trust the information inside. Field crews should be involved before drawings are issued for construction, not after.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('ef46ebeb-6963-49f5-9795-770d10edb5c6', 'seed_r1bbZrNHtN8XRV295e4TM0UTpdUX', '2026-05-16T12:56:34.000Z', 'Case Study: EPC Construction on a Northern Alberta Substation', 'case-study-epc-construction-on-a-northern-alberta-substation', 'EPC construction: how EPC construction cuts cost and schedule risk on Petrochemicals projects in northern Alberta.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'construction'), 'EPC construction', array['Procurement'], array['construction', 'petrochemicals'], 'EPCMst Team', '2026-07-04', 'When Petrochemicals owners in northern Alberta search for "EPC construction", they usually want one thing: a project that stays on budget and on schedule. Field crews should be involved before drawings are issued for construction, not after. When equipment arrives late, every downstream trade waits, and the camp costs keep running. On Petrochemicals projects in northern Alberta, EPC construction is often decided early and paid for late. Data from the last turnaround is the best predictor of the next one, if anyone kept it.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('f1254cd3-3ba7-424a-873f-5724520cd96b', 'seed_bnsczH6i8eiZ1WRemAhG4w8S4NPf', '2026-08-04T07:17:37.000Z', 'Case Study: EPC Engineering at a Gas Processing Plant', 'case-study-epc-engineering-at-a-gas-processing-plant', 'EPC engineering for Power and Utilities owners in Western Canada: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'engineering'), 'EPC engineering', array['Fractional engineer'], array['engineering', 'power and utilities', 'western canada'], 'Leah Tran', '2026-08-29', 'When Power and Utilities owners in Western Canada search for "EPC engineering", they usually want one thing: a project that stays on budget and on schedule. Data from the last turnaround is the best predictor of the next one, if anyone kept it. Cost and schedule risk rarely come from one big decision; they build up from many small ones. We recommend a short review at thirty, sixty and ninety percent design for every gas processing plant. Owners who treat EPC engineering as a box to tick usually discover the cost during construction.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('b8ffac5c-b76a-4df7-900a-58c207dd65ca', 'seed_jQc4MZbKB4d3SLubRLDbe0yT5gdi', '2026-09-07T04:47:31.000Z', 'Case Study: Pipeline Engineering on an Alberta Pipeline Terminal', 'case-study-pipeline-engineering-on-an-alberta-pipeline-terminal', 'Pipeline engineering specialists: how pipeline engineering cuts cost and schedule risk on Oil and Gas projects in Alberta.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'pipeline-engineering'), 'Pipeline engineering specialists', '{}', array['pipeline-engineering', 'oil and gas'], 'EPCMst Team', '2026-10-23', 'When Oil and Gas owners in Alberta search for "Pipeline engineering specialists", they usually want one thing: a project that stays on budget and on schedule. Lessons learned only count if the next project actually reads them. Clear interfaces between contractors prevent the gaps where most rework begins. Our teams have seen the same pattern across several Oil and Gas sites: small gaps early become schedule slips later. We recommend a short review at thirty, sixty and ninety percent design for every pipeline terminal.
