insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('218bd7b4-2783-416c-9807-bddc6f0afd83', 'seed_J9W6pyryQLSnSbV2rGWByVCitowt', '2026-03-04T14:25:04.000Z', 'The Case for Facilities Engineering on Power and Utilities Projects', 'the-case-for-facilities-engineering-on-power-and-utilities-projects', 'Practical lessons from Power and Utilities projects in the Oil Sands region on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'facilities-engineering'), 'Facilities engineering', array['Fractional engineer'], array['facilities-engineering', 'power and utilities'], 'Dana Whitford', '2026-04-09', 'On Power and Utilities projects in the Oil Sands region, facilities engineering is often decided early and paid for late. Our teams have seen the same pattern across several Power and Utilities sites: small gaps early become schedule slips later. We recommend a short review at thirty, sixty and ninety percent design for every upgrader. Owners who treat facilities engineering as a box to tick usually discover the cost during construction.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('91cc0949-8e34-4b9e-b2ad-25e976654cc7', 'seed_Anv6Le8U5QKymazqjdybK6WdgvGu', '2026-06-18T09:34:29.000Z', 'Pre-Vetted EPCM Specialists on Petrochemicals Sites: Common Pitfalls', 'pre-vetted-epcm-specialists-on-petrochemicals-sites-common-pitfalls', 'Practical lessons from Petrochemicals projects in the Oil Sands region on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'specialists'), 'Pre-vetted EPCM specialists', array['Agile project management'], array['specialists', 'oil sands'], 'EPCMst Team', '2026-07-23', 'When Petrochemicals owners in the Oil Sands region search for "Pre-vetted EPCM specialists", they usually want one thing: a project that stays on budget and on schedule. Good specialist staffing is mostly about communication between engineering, procurement and the field. Digital tools help, but only if the people using them trust the information inside. The cheapest change is the one made on paper; the most expensive is the one made in steel. When equipment arrives late, every downstream trade waits, and the camp costs keep running.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('9ee33bcb-ad05-4beb-8b30-e443cf91ae0b', 'seed_Vd6jQxfvwn7mobQoeSjHBipkUYUz', '2026-05-08T12:46:41.000Z', 'Pre Construction: Lessons from a Western Canada Pipeline Terminal', 'pre-construction-lessons-from-a-western-canada-pipeline-terminal', 'Pre construction: how pre-construction planning cuts cost and schedule risk on Water and Wastewater projects in Western Canada.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'construction'), 'Pre construction', array['Construction management', 'Calgary engineering company'], array['construction', 'water and wastewater', 'western canada'], 'EPCMst Team', '2026-06-30', 'Data from the last turnaround is the best predictor of the next one, if anyone kept it. Clear interfaces between contractors prevent the gaps where most rework begins. Cost and schedule risk rarely come from one big decision; they build up from many small ones. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('c955449e-ddb0-4ed5-8b93-380792113f4e', 'seed_ckqQsJGmUGfJqK9EvTDV3xd0kzYq', '2026-07-16T23:09:25.000Z', '3 Lessons on Integrated EPC Delivery from Western Canada Projects', '3-lessons-on-integrated-epc-delivery-from-western-canada-projects', 'Practical lessons from Mining projects in Western Canada on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'engineering'), 'Integrated EPC solutions', array['Design build'], array['engineering', 'mining'], 'Dana Whitford', '2026-08-18', 'Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it. When equipment arrives late, every downstream trade waits, and the camp costs keep running. We recommend a short review at thirty, sixty and ninety percent design for every upgrader. Lessons learned only count if the next project actually reads them.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('bf3cedd3-ec10-4d57-8483-51aca28b313e', 'seed_pPDBgki4zmCgcrVCrqkk2X4TGBoa', '2026-05-28T11:13:12.000Z', 'Facilities Engineering for Alberta Projects', 'facilities-engineering-for-alberta-projects', 'Facilities engineering: how facilities engineering cuts cost and schedule risk on Renewables projects in Alberta.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'facilities-engineering'), 'Facilities engineering', '{}', array['facilities-engineering', 'renewables', 'alberta'], 'EPCMst Team', '2026-08-04', 'When Renewables owners in Alberta search for "Facilities engineering", they usually want one thing: a project that stays on budget and on schedule. Weather, remote access and short construction seasons in Alberta all raise the stakes. Our teams have seen the same pattern across several Renewables sites: small gaps early become schedule slips later. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it. Lessons learned only count if the next project actually reads them.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('4d917261-6c76-4fe2-b097-ad7e1ef0f9a4', 'seed_JtsV6wmNY0Jq0eSrNHRbkydFiT4N', '2026-07-06T00:26:44.000Z', 'Workface Construction: Lessons from a British Columbia Substation: A Field Guide for Owners and Site Teams', 'workface-construction-lessons-from-a-british-columbia-substation', 'Workface construction for Petrochemicals owners in British Columbia: where projects go wrong and what good looks like. Includes a checklist for owners, contractors and site teams working through the next season.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'worksite-management'), 'Workface construction', '{}', '{}', 'Ravi Menon', '2026-08-27', 'When Petrochemicals owners in British Columbia search for "Workface construction", they usually want one thing: a project that stays on budget and on schedule. Owners who treat workface planning as a box to tick usually discover the cost during construction. Data from the last turnaround is the best predictor of the next one, if anyone kept it. Our teams have seen the same pattern across several Petrochemicals sites: small gaps early become schedule slips later. Vendors respond better when expectations are written down and measured the same way every time.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('98fd80c9-e43a-4142-b80f-b951311fbc00', 'seed_Mh5rD4Q6tGohcoY7PHSNzDNyE8y2', '2026-07-14T09:16:29.000Z', 'Calgary Engineering Company: Lessons from a BC Substation', 'calgary-engineering-company-lessons-from-a-bc-substation', 'Practical lessons from Oil and Gas projects in northern Alberta on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'engineering'), 'Calgary engineering company', array['EPC contracts', 'Agile project management'], array['engineering', 'oil and gas'], 'Ravi Menon', '2026-09-07', 'When Oil and Gas owners in northern Alberta search for "Calgary engineering company", they usually want one thing: a project that stays on budget and on schedule. On Oil and Gas projects in northern Alberta, local engineering support is often decided early and paid for late. Our teams have seen the same pattern across several Oil and Gas sites: small gaps early become schedule slips later. Weather, remote access and short construction seasons in northern Alberta all raise the stakes. The cheapest change is the one made on paper; the most expensive is the one made in steel.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('bd3d34ee-ccd8-4a62-8456-3f78a745cc62', 'seed_7tqxMBe9Wfi8mvbh3S3pWZTFeBF5', '2026-04-10T22:36:38.000Z', '4 Lessons on Local Engineering Support from Alberta Projects', '4-lessons-on-local-engineering-support-from-alberta-projects', null, (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'engineering'), 'Calgary engineering company', '{}', array['engineering', 'alberta'], 'EPCMst Team', null, '', 'draft', 'c5069a2a-6f83-43ad-bbc5-dfcee8150d24', null, null, null, null, null, '2026-04-18T22:36:38.000Z', '2026-04-18T22:36:38.000Z');
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('89503215-e099-4a6f-9811-00d3b1539fd4', 'seed_is6m6Hx1JU5pMCsmcmapdooy1Sda', '2026-06-22T07:13:29.000Z', 'Pre-Vetted EPCM Specialists on Petrochemicals Sites: Common Pitfalls', 'pre-vetted-epcm-specialists-on-petrochemicals-sites-common-pitfalls-2', 'Pre-vetted EPCM specialists for Petrochemicals owners in northern Alberta: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'specialists'), 'Pre-vetted EPCM specialists', array['Construction management'], array['specialists', 'petrochemicals'], 'Marcus Okafor', '2026-08-09', 'When Petrochemicals owners in northern Alberta search for "Pre-vetted EPCM specialists", they usually want one thing: a project that stays on budget and on schedule. Weather, remote access and short construction seasons in northern Alberta all raise the stakes. A simple checklist, reviewed at each stage gate, catches most of the issues we see. Clear interfaces between contractors prevent the gaps where most rework begins. We recommend a short review at thirty, sixty and ninety percent design for every water treatment plant.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('958cd386-86d8-4a4d-939b-1382daba8de3', 'seed_o9hEiHvcdzKjzuyAt2nAJkA6A193', '2026-07-26T13:46:01.000Z', 'The Case for EPC Engineering on Water and Wastewater Projects', 'the-case-for-epc-engineering-on-water-and-wastewater-projects', 'EPC engineering: how EPC engineering cuts cost and schedule risk on Water and Wastewater projects in Alberta.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'engineering'), 'EPC engineering', '{}', array['engineering', 'water and wastewater'], 'Leah Tran', '2026-09-08', 'When Water and Wastewater owners in Alberta search for "EPC engineering", they usually want one thing: a project that stays on budget and on schedule. Digital tools help, but only if the people using them trust the information inside. Vendors respond better when expectations are written down and measured the same way every time. Our teams have seen the same pattern across several Water and Wastewater sites: small gaps early become schedule slips later. Field crews should be involved before drawings are issued for construction, not after.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('1d01a41f-defe-4bed-834b-2fff3c8c7c6c', 'seed_wwLuXNDwwpJB2YJExgs6U5TkQS1K', '2026-08-07T03:07:35.000Z', 'A Practical Guide to Environmental Compliance in Oil and Gas', 'a-practical-guide-to-environmental-compliance-in-oil-and-gas', 'Environmental engineering compliance: how environmental compliance cuts cost and schedule risk on Oil and Gas projects in the Oil Sands region.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'water-management'), 'Environmental engineering compliance', array['Project development plan'], array['water-management', 'oil and gas', 'oil sands'], 'EPCMst Team', '2026-09-10', 'The cheapest change is the one made on paper; the most expensive is the one made in steel. Vendors respond better when expectations are written down and measured the same way every time. Measuring progress weekly, with the same yardstick, keeps surprises small. Lessons learned only count if the next project actually reads them.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('9f0de1a0-c0ec-465d-8476-07194afa8488', 'seed_v63JESww5CtsWxjDBXFAsj208KSz', '2026-05-16T17:12:11.000Z', 'The Case for Project Development Planning on Renewables Projects', 'the-case-for-project-development-planning-on-renewables-projects', 'Project development plan for Renewables owners in northern Alberta: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'project-management'), 'Project development plan', array['Calgary engineering company'], array['project-management', 'northern alberta'], 'EPCMst Team', '2026-07-18', 'Cost and schedule risk rarely come from one big decision; they build up from many small ones. A simple checklist, reviewed at each stage gate, catches most of the issues we see. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it. Data from the last turnaround is the best predictor of the next one, if anyone kept it.
